/// <summary>Main</summary>
/// <param name = "_args">Arguments</param>
public static void main(Args _args)
{
    METPriceChangeTrackController controller = METPriceChangeTrackController::construct(_args);
    controller.startOperation();
}

    /// <summary>Constuct new object</summary>
    /// <param name = "_args">Args</param>
    /// <param name = "_executionMode">Execution mode</param>
    /// <returns>New Controller Object</returns>
    public static SysOperationController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
    {
        SysOperationController controller = new METPriceChangeTrackController();
        controller.parmExecutionMode(_executionMode);
        controller.parmArgs(_args);
        controller.parmShowDialog(true);

        return controller;
    }

    /// <summary>
    /// New object. Batch calls this method
    ///</summary>

    protected void new()
    {
        super(classstr(METPriceChangeTrackService), methodstr(METPriceChangeTrackService, process), SysOperationExecutionMode::Synchronous);
    }

/// <summary>
/// process can run in new session
